import re

def is_alt(s):
    if s == "":
        return True
    elif len(s) < 2:
        return False
    elif s[0] in 'aeiou' and s[1] in 'aeiou':
        return False
    elif s[0] not in 'aeiou' and s[1] not in 'aeiou':
        return False
    else:
        return not re.search('[aeiou]{2}|[^aeiou]{2}', s[1:])
```
